 */
scwin.initCallBack = function (result) {
    return;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        shortcut.add("Alt+1", async function() {
                if (await $c.win.confirm("원격제어 사이트로 접속합니다.")) {
                    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
                    const target = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "about:blank", unresolved: "nav:" + "about:blank" }; })();
                    target.location.href = "https://remote.krx.co.kr/";
                }
            }, { 'type': 'keydown', 'propagate': true, 'target': document });
        scwin.checkDefaultCert();
        cwInit("initCallBack");
        await scwin.showMessage();
        scwin.checkTimeOut();
        scwin.checkSesOut();
        $("#ipt_userId").bind("blur", function() {
                if ($(this).val().length === 0) {
                    $c.util.getComponent('txt_userIdLavel').setLabel("아이디");
                } else {
                    $c.util.getComponent('txt_userIdLavel').setLabel("");
                }
        });
        $("#ipt_userPw").bind("blur", function() {
                if ($(this).val().length === 0) {
                    $c.util.getComponent('txt_userPwLavel').setLabel("비밀번호");
                } else {
                    $c.util.getComponent('txt_userPwLavel').setLabel("");
                }
        });
        const div1 = $c.util.getComponent("auto_logout").getStyle('display');
        const div2 = $c.util.getComponent("auto_sesOut").getStyle('display');
        const div3 = $c.util.getComponent("login_alert").getStyle('display');
        if (div1 === '' && div2 === '' && div3 === '' && (String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? "")))) === '' && (String(((dma_pageContext.get("errorCode") ?? "")) == null ? '' : ((dma_pageContext.get("errorCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("errorCode") ?? "")) == null ? '' : ((dma_pageContext.get("errorCode") ?? "")))) === '') {
            for (let i = 0; i < (function(){ throw 'unresolved:list:notiArrList'; })(); i++) {
                if (scwin.getCookie((String(((function(){ throw 'unresolved:list:notiArrList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:notiArrList'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:notiArrList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:notiArrList'; })())))) !== (String(((function(){ throw 'unresolved:list:notiArrList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:notiArrList'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:notiArrList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:notiArrList'; })())))) {
                    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
                    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/external/notice/fil/${notiArrList[__i].popup_file}.html", unresolved: "nav:" + "/external/notice/fil/${notiArrList[__i].popup_file}.html" }; })();
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(login vs announcement) — 어느 쪽인지 정할 근거가 없다

