 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.timeOut = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.timeOut !== "undefined" && scwin.timeOut !== null ? scwin.timeOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "timeOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("timeOut"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.timeOut !== "undefined" && scwin.timeOut !== null ? scwin.timeOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "timeOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("timeOut")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.timeOut !== "undefined" && scwin.timeOut !== null ? scwin.timeOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "timeOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("timeOut"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.timeOut !== "undefined" && scwin.timeOut !== null ? scwin.timeOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "timeOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("timeOut"))));
        scwin.test1 = '' + dma_pageContext.get("method") + '';
        scwin.sesOut = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.sesOut !== "undefined" && scwin.sesOut !== null ? scwin.sesOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sesOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("sesOut"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.sesOut !== "undefined" && scwin.sesOut !== null ? scwin.sesOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sesOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("sesOut")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.sesOut !== "undefined" && scwin.sesOut !== null ? scwin.sesOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sesOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("sesOut"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.sesOut !== "undefined" && scwin.sesOut !== null ? scwin.sesOut : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sesOut" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("sesOut"))));
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil45000.onpageload' });
