/**
 * @method
 * @name tx_relogin
 * @description relogin 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_relogin = async function () {
    const sbmOptions = {
        id: "tx_relogin",
        method: "post",
        action: "/main/login.do?method=reLogin",
        ref: "dma_reloginReq",
        target: "dlt_announcementList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_login
 * @description login 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_login = async function () {
    const sbmOptions = {
        id: "tx_login",
        method: "post",
        action: "/main/login.do?method=login",
        ref: "dma_loginReq",
        target: "dlt_announcementList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_SendForm
 * @description Send Form 서버 호출
