/**
 * @method
 * @name checkUserAgent
 * @description check User Agent 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkUserAgent = async function () {
    const agentInfo = navigator.userAgent.toLowerCase();
    let version = 0;
    const name = navigator.appName;
    let browserType = "others";
    let word = "others";
    if (name === "Microsoft Internet Explorer") {
        browserType = "msie ";
    } else {
        if (agentInfo.search("trident") > -1) {
            word = "trident/.*rv:";
            browserType = "IE";
        } else {
            if (agentInfo.search("edg") > -1) {
                word = "edg\/";
                browserType = "Edge";
            }
        }
    }
    let ua_msg = "";
    await $c.win.alert(">> name : " + name + "\n>> word : " + word + "\n>> agentInfo : " + agentInfo);
    if (browserType !== "others") {
        version = await scwin.checkIEVersion(word, agentInfo);
        const majorVer = version.split(".")[0];
        if (browserType === "msie" || browserType === "IE") {
            ua_msg = "2022년 6월 15일부터 Internet Explorer 11 브라우저의 공식 지원이 종료됩니다.\n시스템의 안정적 사용을 위하여 'Microsoft Edge' 최신 버전(버전 100 이상)을 설치하신 후에, Microsoft Edge 브라우저를 사용하여 이용해 주시기 바랍니다.";
        } else {
            if (browserType === "Edge") {
                if (majorVer < 100) {
                    ua_msg = "한국거래소 KIND 제출시스템은 'Microsoft Edge'가 아닌 다른 브라우저에서 일부 기능이 제한됩니다.\n시스템의 안정적 사용을 위하여 'Microsoft Edge 100' 이상 버전을 사용하시기 바랍니다.";
                }
            }
        }
    } else {
        ua_msg = "한국거래소 KIND 제출시스템은 'Microsoft Edge'가 아닌 다른 브라우저에서 일부 기능이 제한됩니다.\n시스템의 안정적 사용을 위하여 'Microsoft Edge' 최신 버전(버전 100 이상)을 설치하신 후에, Microsoft Edge 브라우저를 사용하여 이용해 주시기 바랍니다.";
    }
    if (ua_msg.length > 0) {
        await $c.win.alert(ua_msg);
        return true;
    }
};

/**
 * @method
 * @name checkIEVersion
 * @description check IEVersion 처리
 * @param {*} word word
 * @param {*} agentInfo agentInfo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIEVersion = async function (word, agentInfo) {
    let version = "N/A";
    let regExpStr = "";
    if (word === "trident/.*rv:") {
        regExpStr = "([0-9]{1,})(\\.{0,}[0-9]{0,1})";
    } else {
        if (word === "edg\/") {
            regExpStr = "([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)";
        }
    }
    const reg = new RegExp(word + regExpStr);
    if (reg.exec(agentInfo) != null) {
        version = RegExp.$1 + RegExp.$2;
    }
    await $c.win.alert("checkIEVersion - version : " + version);
    return version;
};

