/**
 * @method
 * @name setDefaultCert
 * @description set Default Cert 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultCert = function () {
    scwin.setCookie("defaultCert", "defaultCert", 15);
};

/**
 * @method
 * @name releaseDefaultCert
 * @description release Default Cert 처리
 * @returns {void}
 * @hidden N
 */
scwin.releaseDefaultCert = function () {
    scwin.delCookie("defaultCert");
};

/**
 * @method
 * @name setCookie
 * @description set Cookie 처리
 * @param {*} name name
 * @param {*} value value
 * @param {*} expiredays expiredays
 * @returns {void}
 * @hidden N
 */
scwin.setCookie = function (name, value, expiredays) { $c.util.setSessionStorage(name, value); };

/**
 * @method
 * @name delCookie
 * @description del Cookie 처리
 * @param {*} name name
 * @returns {void}
 * @hidden N
 */
scwin.delCookie = function (name) { $c.util.removeSessionStorage(name); };

/**
 * @method
 * @name getCookie
 * @description get Cookie 처리
 * @param {*} Name Name
 * @returns {void}
 * @hidden N
 */
scwin.getCookie = function (Name) { const v = $c.util.getSessionStorage(Name); return (v === undefined || v === null) ? '' : v; };

